// scenario: three-products-set-remove · sha256:d1d829e77f23b900d681dcfa4372a9fef451b219dc44d06aded9163fe1ac8881
// request: Add three different products. Set the first to 2 units and the third to 4. Remove the second. Check the total after every change.
// body-sha256: 84198e856a08b93ecff14ce3ae2052380bf30d490ecca7413b53ae7bdac2dd19
import { test } from '../support/core/fixtures';

test.use({ preconditions: ['empty-cart', 'guest', 'no-geolocation'], priceSource: 'ui' });

test('Cart total after adding three products, setting the quantities of the first and third and removing the second', async ({ shopper }) => {
  const a = await shopper.add({ pick: 'first-available', filters: { needQty: 2 } }, 1);
  await shopper.checkTotal('S1');

  const b = await shopper.add({ pick: 'next-available', distinctFrom: [a] }, 1);
  await shopper.checkTotal('S2');

  const c = await shopper.add({ pick: 'next-available', distinctFrom: [a, b], filters: { needQty: 4 } }, 1);
  await shopper.checkTotal('S3');

  await shopper.setQuantity(a, 2);
  await shopper.checkTotal('S4');

  await shopper.setQuantity(c, 4);
  await shopper.checkTotal('S5');

  await shopper.remove(b);
  await shopper.checkTotal('S6');
});
